1	import React from 'react';
2	import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';
3	import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
4	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
5	import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
6	import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
7	import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';
8	
9	export type ZimmWishlistAuthDrawerProps = {
10	  /**
11	   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
12	   * flows — those trigger a full browser redirect; the user lands back already logged in.
13	   */
14	  onAuthSuccess?: () => void;
15	  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
16	   *  auth-gate handler — call the original action via onAuthSuccess instead. */
17	  children: React.ReactElement;
18	};
19	
20	/**
21	 * Organism — wraps a single trigger element and gates its action behind auth.
22	 * If the customer is already registered the original onClick fires immediately.
23	 * If not, the Zimmermann auth drawer opens instead (passwordless email + optional social IDPs).
24	 *
25	 * Drop-in replacement for `withRegistration(Button)` on wishlist-specific entry points.
26	 * All SDK and auth logic lives in `useWishlistAuthDrawer` — this component is purely presentational.
27	 */
28	export const ZimmWishlistAuthDrawer = ({ onAuthSuccess, children }: ZimmWishlistAuthDrawerProps) => {
29	  const {
30	    isOpen,
31	    handleDrawerClose,
32	    handleTriggerClick,
33	    triggerRef,
34	    drawerTitle,
35	    description,
36	    emailValue,
37	    onEmailChange,
38	    onSendCode,
39	    onSignInWithApple,
40	    onSignInWithGoogle,
41	    isSocialEnabled,
42	    isPasswordlessEnabled,
43	    emailInputRef,
44	    onCreateAccount,
45	    isOtpAuthOpen,
46	    onOtpAuthClose,
47	    form,
48	    handlePasswordlessLogin,
49	    handleOtpVerification,
50	    registerModal,
51	  } = useWishlistAuthDrawer({ onAuthSuccess });
52	
53	  return (
54	    <>
55	      {React.cloneElement(React.Children.only(children), { onClick: handleTriggerClick })}
56	      <ZimmDrawer
57	        isOpen={isOpen}
58	        onClose={handleDrawerClose}
59	        size="small"
60	        title={drawerTitle}
61	        finalFocusRef={triggerRef}
62	        initialFocusRef={emailInputRef}
63	      >
64	        <ErrorFallback>
65	          <ZimmAuthDrawerContent
66	            description={description}
67	            emailValue={emailValue}
68	            onEmailChange={onEmailChange}
69	            onSendCode={onSendCode}
70	            onSignInWithApple={onSignInWithApple}
71	            onSignInWithGoogle={onSignInWithGoogle}
72	            onCreateAccount={onCreateAccount}
73	            socialEnabled={isSocialEnabled}
74	            passwordlessEnabled={isPasswordlessEnabled}
75	            initialFocusRef={emailInputRef}
76	          />
77	        </ErrorFallback>
78	      </ZimmDrawer>
79	      <AuthModal {...registerModal} />
80	      <OtpAuth
81	        isOpen={isOtpAuthOpen}
82	        onClose={onOtpAuthClose}
83	        form={form}
84	        handleSendEmailOtp={handlePasswordlessLogin}
85	        handleOtpVerification={handleOtpVerification}
86	        hideCheckoutAsGuestButton={true}
87	      />
88	    </>
89	  );
90	};
