1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { EmailForm } from './emailForm';
4	import { SocialButtons } from './socialButtons';
5	import { CreateAccount } from './createAccount';
6	
7	const ZIMM_AUTH_DRAWER_CONTENT_RECIPE = 'ZimmAuthDrawerContent';
8	
9	export type ZimmAuthDrawerContentProps = {
10	  description?: string;
11	  emailValue: string;
12	  onEmailChange: (val: string) => void;
13	  onSendCode: () => Promise<{ success: boolean; error?: string } | void> | void;
14	  onSignInWithApple?: () => void;
15	  onSignInWithGoogle?: () => void;
16	  onCreateAccount: () => void;
17	  socialEnabled?: boolean;
18	  /** Error message to display below the social sign-in buttons (e.g. IDP redirect failure). */
19	  socialError?: string;
20	  /** When false the email/OTP form is hidden — passwordless login is not configured for this site. */
21	  passwordlessEnabled?: boolean;
22	  isLoading?: boolean;
23	  /** Forwarded to the email input — pass the same ref given to ZimmDrawer's initialFocusRef
24	   *  so focus lands on the input (not the close button) when the drawer opens. */
25	  initialFocusRef?: React.RefObject<HTMLInputElement>;
26	};
27	
28	/**
29	 * Zimmermann-branded login view rendered inside ZimmDrawer for the wishlist auth panel.
30	 * Composes email form, optional social sign-in, and create-account sections (SFCC-742).
31	 */
32	export const ZimmAuthDrawerContent = ({
33	  description,
34	  emailValue,
35	  onEmailChange,
36	  onSendCode,
37	  onSignInWithApple,
38	  onSignInWithGoogle,
39	  onCreateAccount,
40	  socialEnabled = false,
41	  passwordlessEnabled = true,
42	  isLoading = false,
43	  socialError,
44	  initialFocusRef,
45	}: ZimmAuthDrawerContentProps) => {
46	  const styles = useMultiStyleConfig(ZIMM_AUTH_DRAWER_CONTENT_RECIPE, {});
47	
48	  const showSocial = socialEnabled && (!!onSignInWithApple || !!onSignInWithGoogle);
49	
50	  return (
51	    <chakra.div __css={styles.root}>
52	      <chakra.div __css={styles.content}>
53	        {description && <chakra.p __css={styles.description}>{description}</chakra.p>}
54	        {passwordlessEnabled && (
55	          <chakra.div __css={styles.emailForm}>
56	            <EmailForm
57	              emailValue={emailValue}
58	              onEmailChange={onEmailChange}
59	              onSubmit={onSendCode}
60	              isLoading={isLoading}
61	              inputRef={initialFocusRef}
62	            />
63	          </chakra.div>
64	        )}
65	      </chakra.div>
66	
67	      {showSocial && (
68	        <>
69	          <chakra.div __css={styles.divider} aria-hidden={true} />
70	          <chakra.div __css={styles.socialGroup}>
71	            <SocialButtons onSignInWithApple={onSignInWithApple} onSignInWithGoogle={onSignInWithGoogle} />
72	            {socialError && (
73	              <chakra.p role="alert" __css={styles.socialError}>
74	                {socialError}
75	              </chakra.p>
76	            )}
77	          </chakra.div>
78	        </>
79	      )}
80	
81	      <chakra.div __css={styles.signupSection}>
82	        <chakra.div __css={styles.divider} aria-hidden={true} />
83	        <CreateAccount onCreateAccount={onCreateAccount} />
84	      </chakra.div>
85	    </chakra.div>
86	  );
87	};
