1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmSocialButton } from 'app/components/ui-kits/atoms/zimmSocialButton';
4	import { ZimmAppleSignInIcon, ZimmGoogleSignInIcon } from 'app/components/icons';
5	import { useUiCopy } from 'app/hooks/useUiCopy';
6	
7	const ZIMM_AUTH_DRAWER_CONTENT_RECIPE = 'ZimmAuthDrawerContent';
8	
9	type SocialButtonsProps = {
10	  onSignInWithApple?: () => void;
11	  onSignInWithGoogle?: () => void;
12	};
13	
14	export const SocialButtons = ({ onSignInWithApple, onSignInWithGoogle }: SocialButtonsProps) => {
15	  const { t } = useUiCopy();
16	  const signInWithApple = t('login.drawer.signInWithApple', 'Sign in with Apple');
17	  const signInWithGoogle = t('login.drawer.signInWithGoogle', 'Sign in with Google');
18	  const styles = useMultiStyleConfig(ZIMM_AUTH_DRAWER_CONTENT_RECIPE, {});
19	
20	  return (
21	    <chakra.div __css={styles.socialStack}>
22	      {onSignInWithApple && (
23	        <ZimmSocialButton icon={<ZimmAppleSignInIcon />} label={signInWithApple} onClick={onSignInWithApple} />
24	      )}
25	      {onSignInWithGoogle && (
26	        <ZimmSocialButton icon={<ZimmGoogleSignInIcon />} label={signInWithGoogle} onClick={onSignInWithGoogle} />
27	      )}
28	    </chakra.div>
29	  );
30	};
