// Header right section recipe — desktop: search input + icon buttons; mobile: search + bag.
// Styles migrated from Header.baseStyle.{iconGroup,searchWrapper} in header/header.css.ts (previously theme/components/header.ts).
export const ZimmHeaderRightBar = {
  parts: [
    'section',
    'searchWrapper',
    'tabletSearch',
    'iconGroup',
    'closeControl',
    'mobileSection',
    'popoverNavList',
    'popoverNavItem',
    'signoutRow',
  ],
  baseStyle: {
    // Outer tablet+desktop wrapper — hidden below tablet (768px), flex row at md+.
    // gap: var(--alias/space/500, 20px) per Figma node 40000259:10795 (between search and icons).
    // Gap has visual effect only at desktop (xl) when both searchWrapper and iconGroup are visible.
    section: {
      display: 'none',
      [`@media (min-width: ${BP.tablet})`]: {
        display: 'flex',
      },
      alignItems: 'center',
      gap: 'var(--zimm-scale-l)',
    },
    // Search input container — hidden below desktop (xl), flex at xl+.
    // Figma node 40000259:10795: 180px wide. ZimmSearchInput's own recipe defines its height
    // (24px) — no fixed height here. At tablet (md), a search icon appears in tabletSearch instead.
    searchWrapper: {
      display: 'none',
      [`@media (min-width: ${BP.desktop})`]: {
        display: 'flex',
        alignItems: 'center',
      },
      width: 'var(--zimm-scale-4500)',
    },
    // Tablet-only search icon wrapper — flex at md, hidden at desktop (xl+).
---
      gap: 'var(--zimm-scale-m)',
      [`@media (min-width: ${BP.desktop})`]: {
        gap: 0,
      },
    },
    // "CLOSE" label + X icon, replaces searchWrapper+iconGroup when a mega menu/drawer is open.
    // audit-allow: gap is a provisional placeholder, no confirmed Figma spec.
    // height matches the icon buttons it replaces — topBar's height is 'auto', so without this
    // the shorter close control shrinks the whole row and reflows everything below it.
    closeControl: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-xs)',
      cursor: 'pointer',
      height: { md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' },
    },
    // Mobile-only icons section — flex at base, hidden at tablet (768px+).
    // Figma node 40000259:13476: 24×24px containers, 20px icon visual, 16px gap.
    mobileSection: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-m)',
      [`@media (min-width: ${BP.tablet})`]: {
        display: 'none',
      },
    },
    // Account popover nav list — block list with no bullets or default UA margin/padding.
    popoverNavList: {
      listStyleType: 'none',
      padding: 0,
      margin: 0,
    },
    // Account popover nav item — position:relative for any future active/hover indicator.
    popoverNavItem: {
      position: 'relative',
    },
    // Signout button inner row — icon + text label rendered side by side.
    signoutRow: {
      display: 'flex',
      alignItems: 'center',
    },
  },
};

